//! Strict, bounded WebAssembly binary decoding for the supported feature set.
use crate::model::*;

type Result<T> = std::result::Result<T, String>;

struct Reader<'a> { bytes: &'a [u8], pos: usize }
impl<'a> Reader<'a> {
    fn new(bytes: &'a [u8]) -> Self { Self { bytes, pos: 0 } }
    fn remaining(&self) -> usize { self.bytes.len() - self.pos }
    fn byte(&mut self) -> Result<u8> {
        let b = *self.bytes.get(self.pos).ok_or("unexpected end of binary")?;
        self.pos += 1; Ok(b)
    }
    fn take(&mut self, n: usize) -> Result<&'a [u8]> {
        if n > self.remaining() { return Err("unexpected end of binary".into()); }
        let start = self.pos; self.pos += n; Ok(&self.bytes[start..self.pos])
    }
    fn uint(&mut self) -> Result<u32> {
        let mut value = 0u32;
        for n in 0..5 {
            let b = self.byte()?;
            if n == 4 && b & 0xf0 != 0 { return Err("invalid u32 LEB128 encoding".into()); }
            value |= ((b & 127) as u32) << (n * 7);
            if b & 128 == 0 { return Ok(value); }
        }
        Err("u32 LEB128 too long".into())
    }
    fn sint(&mut self, bits: u32) -> Result<i64> {
        let count = bits.div_ceil(7);
        let mut value = 0u64;
        for n in 0..count {
            let b = self.byte()?;
            let shift = n * 7;
            if n + 1 == count {
                let used = bits - shift;
                let mask = 0x7fu8 << used;
                let sign = 1u8 << (used - 1);
                if b & 128 != 0 || (b & mask != if b & sign != 0 { mask & 127 } else { 0 }) {
                    return Err(format!("invalid signed {bits}-bit LEB128 encoding"));
                }
            }
            value |= ((b & 127) as u64) << shift;
            if b & 128 == 0 {
                let width = shift + 7;
                if b & 64 != 0 && width < 64 { value |= (!0u64) << width; }
                return Ok(value as i64);
            }
        }
        Err("signed LEB128 too long".into())
    }
    fn zero(&mut self) -> Result<()> {
        if self.byte()? != 0 { return Err("nonzero reserved byte (multiple memories/tables are unsupported)".into()); }
        Ok(())
    }
    fn count(&mut self) -> Result<usize> {
        let n = self.uint()? as usize;
        if n > self.remaining() { return Err("vector count exceeds available binary data".into()); }
        Ok(n)
    }
    fn name(&mut self) -> Result<String> {
        let n = self.uint()? as usize;
        let bytes = self.take(n)?;
        Ok(std::str::from_utf8(bytes).map_err(|_| "name is not valid UTF-8")?.to_owned())
    }
    fn ty(&mut self) -> Result<Ty> {
        match self.byte()? {
            0x7f => Ok(Ty::I32), 0x7e => Ok(Ty::I64), 0x7d => Ok(Ty::F32),
            0x7c => Ok(Ty::F64), 0x7b => Ok(Ty::V128),
            _ => Err("unsupported or invalid value type".into()),
        }
    }
    fn types(&mut self) -> Result<Vec<Ty>> {
        let n = self.count()?; (0..n).map(|_| self.ty()).collect()
    }
    fn limits(&mut self, memory: bool) -> Result<Limits> {
        let flags = self.byte()?;
        if flags > 1 { return Err("shared, 64-bit, and other extended limits are unsupported".into()); }
        let min = self.uint()?;
        let max = if flags == 1 { Some(self.uint()?) } else { None };
        if max.is_some_and(|x| x < min) || (memory && (min > 65536 || max.is_some_and(|x| x > 65536))) {
            return Err("invalid limits".into());
        }
        Ok(Limits { min, max })
    }
    fn memarg(&mut self, i: &mut Instr) -> Result<()> {
        i.a = self.uint()?; i.b = self.uint()?; Ok(())
    }
    fn instruction(&mut self) -> Result<Instr> {
        let op = self.byte()? as u32;
        let mut i = Instr { op, ..Instr::default() };
        match op {
            0x02..=0x04 => { i.imm = self.sint(33)?; }
            0x0c | 0x0d | 0x10 | 0x20..=0x24 => { i.a = self.uint()?; }
            0x0e => {
                let n = self.count()?;
                for _ in 0..n { i.list.push(self.uint()?); }
                i.a = self.uint()?;
            }
            0x11 => { i.a = self.uint()?; self.zero()?; }
            0x28..=0x3e => self.memarg(&mut i)?,
            0x3f | 0x40 => self.zero()?,
            0x41 => i.imm = self.sint(32)?,
            0x42 => i.imm = self.sint(64)?,
            0x43 => i.bytes[..4].copy_from_slice(self.take(4)?),
            0x44 => i.bytes[..8].copy_from_slice(self.take(8)?),
            0xfc => {
                let sub = self.uint()?;
                if sub > 14 { return Err(format!("unsupported 0xfc opcode {sub}")); }
                i.op = 0xfc00 + sub;
                match sub {
                    0..=7 => (),
                    8 => { i.a = self.uint()?; self.zero()?; }
                    9 | 13 => { i.a = self.uint()?; }
                    10 | 14 => { self.zero()?; self.zero()?; }
                    11 => self.zero()?,
                    12 => { i.a = self.uint()?; self.zero()?; }
                    _ => unreachable!(),
                }
            }
            0xfd => {
                let sub = self.uint()?;
                if crate::validate::simd_signature(sub).is_none() {
                    return Err(format!("invalid or unsupported SIMD opcode {sub:#x}"));
                }
                i.op = 0xfd00 + sub;
                match sub {
                    0..=11 | 0x5c | 0x5d => self.memarg(&mut i)?,
                    12 | 13 => i.bytes.copy_from_slice(self.take(16)?),
                    0x15..=0x22 => i.imm = self.byte()? as i64,
                    0x54..=0x5b => { self.memarg(&mut i)?; i.imm = self.byte()? as i64; }
                    _ => (),
                }
            }
            0x00 | 0x01 | 0x05 | 0x0b | 0x0f | 0x1a | 0x1b | 0x45..=0xc4 => (),
            _ => return Err(format!("unsupported or invalid opcode {op:#x}")),
        }
        Ok(i)
    }
    fn expr(&mut self) -> Result<Vec<Instr>> {
        let mut code = Vec::new();
        let mut depth = 1usize;
        while depth != 0 {
            let i = self.instruction()?;
            match i.op { 2..=4 => depth += 1, 0x0b => depth -= 1, _ => () }
            code.push(i);
        }
        Ok(code)
    }
    fn done(&self) -> Result<()> {
        if self.remaining() != 0 { Err("trailing bytes in section or function body".into()) } else { Ok(()) }
    }
}

/// Decode and fully validate a binary module before exposing it to code generation.
pub fn parse(bytes: &[u8]) -> Result<Module> {
    let mut r = Reader::new(bytes);
    if r.take(8)? != b"\0asm\x01\0\0\0" { return Err("invalid WebAssembly magic or version".into()); }
    let mut m = Module::default();
    let mut seen = [false; 13];
    let mut last_rank = 0;
    let mut defined_types = Vec::new();
    let mut bodies = 0usize;
    while r.remaining() != 0 {
        let id = r.byte()? as usize;
        if id > 12 { return Err(format!("unsupported section id {id}")); }
        let n = r.uint()? as usize;
        let mut s = Reader::new(r.take(n)?);
        if id == 0 { s.name()?; continue; }
        let rank = match id { 12 => 10, 10 => 11, 11 => 12, _ => id };
        if seen[id] || rank <= last_rank { return Err("duplicate or out-of-order section".into()); }
        seen[id] = true; last_rank = rank;
        match id {
            1 => {
                let n = s.count()?;
                for _ in 0..n {
                    if s.byte()? != 0x60 { return Err("unsupported non-function type".into()); }
                    m.types.push(FuncType { params: s.types()?, results: s.types()? });
                }
            }
            2 => {
                let n = s.count()?;
                for _ in 0..n {
                    let module = s.name()?; let name = s.name()?;
                    if s.byte()? != 0 { return Err("non-function imports are unsupported by this ABI".into()); }
                    m.funcs.push(Func { type_idx: s.uint()?, import: Some((module, name)), locals: vec![], code: vec![] });
                }
            }
            3 => {
                let n = s.count()?;
                for _ in 0..n { defined_types.push(s.uint()?); }
            }
            4 => {
                let n = s.count()?;
                if n > 1 { return Err("multiple tables are unsupported".into()); }
                if n == 1 {
                    if s.byte()? != 0x70 { return Err("only funcref tables are supported".into()); }
                    m.table = Some(s.limits(false)?);
                }
            }
            5 => {
                let n = s.count()?;
                if n > 1 { return Err("multiple memories are unsupported".into()); }
                if n == 1 { m.memory = Some(s.limits(true)?); }
            }
            6 => {
                let n = s.count()?;
                for _ in 0..n {
                    let ty = s.ty()?;
                    let mutable = match s.byte()? { 0 => false, 1 => true, _ => return Err("invalid global mutability".into()) };
                    m.globals.push(Global { ty, mutable, init: s.expr()? });
                }
            }
            7 => {
                let n = s.count()?;
                for _ in 0..n { m.exports.push(Export { name: s.name()?, kind: s.byte()?, index: s.uint()? }); }
            }
            8 => m.start = Some(s.uint()?),
            9 => {
                let n = s.count()?;
                for _ in 0..n {
                    let flags = s.uint()?;
                    if flags > 3 { return Err("reference-expression element segments are unsupported".into()); }
                    if flags == 2 && s.uint()? != 0 { return Err("unknown table index".into()); }
                    let offset = if flags == 0 || flags == 2 { s.expr()? } else { vec![] };
                    if flags != 0 && s.byte()? != 0 { return Err("invalid element kind".into()); }
                    let count = s.count()?;
                    let funcs = (0..count).map(|_| s.uint()).collect::<Result<Vec<_>>>()?;
                    m.elems.push(Elem { passive: flags == 1, declarative: flags == 3, offset, funcs });
                }
            }
            10 => {
                bodies = s.count()?;
                if bodies != defined_types.len() { return Err("function and code section counts differ".into()); }
                for &type_idx in &defined_types {
                    let size = s.uint()? as usize;
                    let mut body = Reader::new(s.take(size)?);
                    let n = body.count()?;
                    let mut locals = Vec::new();
                    for _ in 0..n {
                        let count = body.uint()? as usize; let ty = body.ty()?;
                        let len = locals.len().checked_add(count).ok_or("too many locals")?;
                        // Keep adversarial compressed local declarations from exhausting the translator.
                        if len > 1_000_000 { return Err("implementation limit: more than one million function locals".into()); }
                        locals.resize(len, ty);
                    }
                    let code = body.expr()?; body.done()?;
                    m.funcs.push(Func { type_idx, import: None, locals, code });
                }
            }
            11 => {
                let n = s.count()?;
                for _ in 0..n {
                    let flags = s.uint()?;
                    if flags > 2 { return Err("invalid data segment flags".into()); }
                    if flags == 2 && s.uint()? != 0 { return Err("unknown memory index".into()); }
                    let offset = if flags != 1 { s.expr()? } else { vec![] };
                    let size = s.uint()? as usize;
                    m.data.push(Data { passive: flags == 1, offset, bytes: s.take(size)?.to_vec() });
                }
            }
            12 => m.data_count = Some(s.uint()?),
            _ => unreachable!(),
        }
        s.done()?;
    }
    if bodies != defined_types.len() { return Err("missing function bodies".into()); }
    crate::validate::validate(&m)?;
    Ok(m)
}

