            0xfd => {
                let sub = self.uint()?;
                if crate::validate::simd_signature(sub).is_none() {
                    return Err(format!("invalid or unsupported SIMD opcode {sub:#x}"));
                }
                i.op = 0xfd00 + sub;
                match sub {
                    0..=11 | 0x5c | 0x5d => self.memarg(&mut i)?,
                    12 | 13 => i.bytes.copy_from_slice(self.take(16)?),
                    0x15..=0x22 => i.imm = self.byte()? as i64,
                    0x54..=0x5b => { self.memarg(&mut i)?; i.imm = self.byte()? as i64; }
                    _ => (),
                }
            }
            0x00 | 0x01 | 0x05 | 0x0b | 0x0f | 0x1a | 0x1b | 0x45..=0xc4 => (),
            _ => return Err(format!("unsupported or invalid opcode {op:#x}")),
        }
        Ok(i)
    }
    fn expr(&mut self) -> Result<Vec<Instr>> {
        let mut code = Vec::new();
        let mut depth = 1usize;
        while depth != 0 {
            let i = self.instruction()?;
            match i.op { 2..=4 => depth += 1, 0x0b => depth -= 1, _ => () }
            code.push(i);
        }
        Ok(code)
    }
    fn done(&self) -> Result<()> {
        if self.remaining() != 0 { Err("trailing bytes in section or function body".into()) } else { Ok(()) }
    }
}

/// Decode and fully validate a binary module before exposing it to code generation.
pub fn parse(bytes: &[u8]) -> Result<Module> {
    let mut r = Reader::new(bytes);
    if r.take(8)? != b"\0asm\x01\0\0\0" { return Err("invalid WebAssembly magic or version".into()); }
    let mut m = Module::default();
    let mut seen = [false; 13];
    let mut last_rank = 0;
    let mut defined_types = Vec::new();
    let mut bodies = 0usize;
    while r.remaining() != 0 {
        let id = r.byte()? as usize;
        if id > 12 { return Err(format!("unsupported section id {id}")); }
        let n = r.uint()? as usize;
        let mut s = Reader::new(r.take(n)?);
        if id == 0 { s.name()?; continue; }
        let rank = match id { 12 => 10, 10 => 11, 11 => 12, _ => id };
        if seen[id] || rank <= last_rank { return Err("duplicate or out-of-order section".into()); }
        seen[id] = true; last_rank = rank;
        match id {
            1 => {
                let n = s.count()?;
                for _ in 0..n {
                    if s.byte()? != 0x60 { return Err("unsupported non-function type".into()); }
                    m.types.push(FuncType { params: s.types()?, results: s.types()? });
                }
            }
            2 => {
                let n = s.count()?;
                for _ in 0..n {
                    let module = s.name()?; let name = s.name()?;
                    if s.byte()? != 0 { return Err("non-function imports are unsupported by this ABI".into()); }
                    m.funcs.push(Func { type_idx: s.uint()?, import: Some((module, name)), locals: vec![], code: vec![] });
                }
            }
            3 => {
                let n = s.count()?;
                for _ in 0..n { defined_types.push(s.uint()?); }
            }
            4 => {
                let n = s.count()?;
                if n > 1 { return Err("multiple tables are unsupported".into()); }
                if n == 1 {
                    if s.byte()? != 0x70 { return Err("only funcref tables are supported".into()); }
                    m.table = Some(s.limits(false)?);
                }
            }
            5 => {
                let n = s.count()?;
                if n > 1 { return Err("multiple memories are unsupported".into()); }
                if n == 1 { m.memory = Some(s.limits(true)?); }
            }
            6 => {
                let n = s.count()?;
                for _ in 0..n {
                    let ty = s.ty()?;
                    let mutable = match s.byte()? { 0 => false, 1 => true, _ => return Err("invalid global mutability".into()) };
                    m.globals.push(Global { ty, mutable, init: s.expr()? });
                }
            }
            7 => {
                let n = s.count()?;
                for _ in 0..n { m.exports.push(Export { name: s.name()?, kind: s.byte()?, index: s.uint()? }); }
            }
            8 => m.start = Some(s.uint()?),
            9 => {
                let n = s.count()?;
                for _ in 0..n {
                    let flags = s.uint()?;
                    if flags > 3 { return Err("reference-expression element segments are unsupported".into()); }
                    if flags == 2 && s.uint()? != 0 { return Err("unknown table index".into()); }
                    let offset = if flags == 0 || flags == 2 { s.expr()? } else { vec![] };
                    if flags != 0 && s.byte()? != 0 { return Err("invalid element kind".into()); }
                    let count = s.count()?;
                    let funcs = (0..count).map(|_| s.uint()).collect::<Result<Vec<_>>>()?;
                    m.elems.push(Elem { passive: flags == 1, declarative: flags == 3, offset, funcs });
                }
            }
            10 => {
                bodies = s.count()?;
                if bodies != defined_types.len() { return Err("function and code section counts differ".into()); }
                for &type_idx in &defined_types {
                    let size = s.uint()? as usize;
                    let mut body = Reader::new(s.take(size)?);
                    let n = body.count()?;
                    let mut locals = Vec::new();
                    for _ in 0..n {
                        let count = body.uint()? as usize; let ty = body.ty()?;
                        let len = locals.len().checked_add(count).ok_or("too many locals")?;
                        // Keep adversarial compressed local declarations from exhausting the translator.
                        if len > 1_000_000 { return Err("implementation limit: more than one million function locals".into()); }
                        locals.resize(len, ty);
                    }
                    let code = body.expr()?; body.done()?;
                    m.funcs.push(Func { type_idx, import: None, locals, code });
                }
            }
            11 => {
                let n = s.count()?;
                for _ in 0..n {
                    let flags = s.uint()?;
                    if flags > 2 { return Err("invalid data segment flags".into()); }
                    if flags == 2 && s.uint()? != 0 { return Err("unknown memory index".into()); }
                    let offset = if flags != 1 { s.expr()? } else { vec![] };
                    let size = s.uint()? as usize;
                    m.data.push(Data { passive: flags == 1, offset, bytes: s.take(size)?.to_vec() });
                }
            }
            12 => m.data_count = Some(s.uint()?),
            _ => unreachable!(),
        }
        s.done()?;
    }
    if bodies != defined_types.len() { return Err("missing function bodies".into()); }
    crate::validate::validate(&m)?;
    Ok(m)
}

