    fn range(&mut self,addr:&Val,n:&Val,len:&str,code:u32)->String {
        let a=self.raw(format!("zext i32 {} to i64",addr.v));let n=self.raw(format!("zext i32 {} to i64",n.v));let end=self.raw(format!("add i64 {a}, {n}"));let bad=self.raw(format!("icmp ugt i64 {end}, {len}"));self.check(&bad,code);a
    }
    fn take(&mut self,ts:&[Ty])->Result<Vec<Val>,String> {let mut v=Vec::new();for t in ts.iter().rev(){v.push(self.pop(*t)?)}v.reverse();Ok(v)}
    fn peek(&self,ts:&[Ty])->Vec<Val> {self.stack[self.stack.len()-ts.len()..].to_vec()}
    fn stores(&mut self,vs:&[Val],slots:&[String]) {for (v,p) in vs.iter().zip(slots){self.line(format!("store {} {}, ptr {p}, align 1",v.ty.llvm(),v.v));}}
    fn loads(&mut self,ts:&[Ty],slots:&[String])->Vec<Val> {ts.iter().zip(slots).map(|(t,p)|self.value(*t,format!("load {}, ptr {p}, align 1",t.llvm()))).collect()}
    fn block_type(&self,i:&Instr)->(Vec<Ty>,Vec<Ty>) {match i.imm {-64=>(vec![],vec![]),-1=>(vec![],vec![Ty::I32]),-2=>(vec![],vec![Ty::I64]),-3=>(vec![],vec![Ty::F32]),-4=>(vec![],vec![Ty::F64]),-5=>(vec![],vec![Ty::V128]),n=>{let t=&self.m.types[n as usize];(t.params.clone(),t.results.clone())}}}
    fn begin(&mut self,i:&Instr)->Result<(),String> {
        let (params,results)=self.block_type(i);let outer=self.live;
        let cond=if outer&&i.op==4{Some(self.pop(Ty::I32)?)}else{None};
