    }
    fn end(&mut self,is_else:bool)->Result<(),String> {
        let mut f=self.frames.pop().ok_or("bad control frame")?;
        if self.live {let vs=self.take(&f.results)?; if f.kind==3 {
            // Loops branch to parameters, but fall through with results.
            let slots=f.results.iter().map(|t|self.alloca(t.llvm())).collect::<Vec<_>>();self.stores(&vs,&slots);f.slots=slots;
        } else {self.stores(&vs,&f.slots)} self.line(format!("br label %{}",f.end));f.used=true;}
        self.stack.truncate(f.height);
        if is_else {
            self.mark(&f.other);self.live=f.outer;if !self.live {self.line("unreachable");}self.stack.extend(f.saved.clone());f.had_else=true;self.frames.push(f);return Ok(())
        }
        if f.kind==4&&!f.had_else {
            self.mark(&f.other);if f.outer{self.stores(&f.saved,&f.slots);self.line(format!("br label %{}",f.end));f.used=true;}
            else {self.line("unreachable");}
        }
        self.live=f.used;
        // A loop's backedges do not make its end reachable.
        self.mark(&f.end);
        if self.live {let vals=self.loads(&f.results,&f.slots);self.stack.extend(vals);}else{self.line("unreachable");}
        Ok(())
    }
    fn branch(&mut self,depth:u32,conditional:Option<Val>)->Result<(),String> {
        let idx=self.frames.len()-1-depth as usize;let f=self.frames[idx].clone();
        let ts=if f.kind==3{&f.params}else{&f.results};let vs=self.peek(ts);self.stores(&vs,&f.slots);
        let target=if f.kind==3{f.label}else{self.frames[idx].used=true;f.end};
        if let Some(c)=conditional {let c=self.raw(format!("icmp ne i32 {}, 0",c.v));let cont=self.label();self.line(format!("br i1 {c}, label %{target}, label %{cont}"));self.mark(&cont);}
        else{self.line(format!("br label %{target}"));self.live=false;}
        Ok(())
    }
    fn call(&mut self,t:&FuncType,callee:&str)->Result<(),String> {
        let vs=self.take(&t.params)?;let args=vs.iter().map(|v|format!("{} {}",v.ty.llvm(),v.v)).collect::<Vec<_>>().join(", ");let rt=ret_type(t);
        if t.results.is_empty(){self.line(format!("call {rt} {callee}({args})"));}
        else{let v=self.raw(format!("call {rt} {callee}({args})"));if t.results.len()==1{self.push(Val{ty:t.results[0],v})}else{for (j,ty) in t.results.iter().enumerate(){let r=self.value(*ty,format!("extractvalue {rt} {v}, {j}"));self.push(r)}}}
        Ok(())
    }
    fn instr(&mut self,i:&Instr)->Result<(),String> {
        match i.op {2|3|4=>return self.begin(i),5=>return self.end(true),11=>return self.end(false),_=>{}}
        if !self.live{return Ok(())}
        match i.op {
            0=>{self.line("call void @trap(i32 0)");self.line("unreachable");self.live=false;},1=>{},
            12=>self.branch(i.a,None)?,13=>{let c=self.pop(Ty::I32)?;self.branch(i.a,Some(c))?;},
            14=>{let c=self.pop(Ty::I32)?;let default=self.label();let labels=(0..i.list.len()).map(|_|self.label()).collect::<Vec<_>>();let cases=labels.iter().enumerate().map(|(j,l)|format!("i32 {j}, label %{l}")).collect::<Vec<_>>().join(" ");self.line(format!("switch i32 {}, label %{default} [ {cases} ]",c.v));for (&d,l) in i.list.iter().zip(&labels){self.mark(l);self.branch(d,None)?;}self.mark(&default);self.branch(i.a,None)?;},
            15=>self.branch((self.frames.len()-1) as u32,None)?,
            16=>{let t=self.m.types[self.m.funcs[i.a as usize].type_idx as usize].clone();self.call(&t,&format!("@f{}",i.a))?;},
            17=>{let idx=self.pop(Ty::I32)?;let x=self.raw(format!("zext i32 {} to i64",idx.v));let lim=self.m.table.as_ref().unwrap().min;let bad=self.raw(format!("icmp uge i64 {x}, {lim}"));self.check(&bad,5);let base=self.raw("load ptr, ptr @table.base");let p=self.raw(format!("getelementptr i32, ptr {base}, i64 {x}"));let id=self.raw(format!("load i32, ptr {p}, align 4"));let null=self.raw(format!("icmp eq i32 {id}, 0"));self.check(&null,6);let fi=self.raw(format!("sub i32 {id}, 1"));let tp=self.raw(format!("getelementptr [{} x i32], ptr @func.types, i32 0, i32 {fi}",self.m.funcs.len()));let ty=self.raw(format!("load i32, ptr {tp}"));let mismatch=self.raw(format!("icmp ne i32 {ty}, {}",type_id(self.m,i.a)));self.check(&mismatch,7);let pp=self.raw(format!("getelementptr [{} x ptr], ptr @func.ptrs, i32 0, i32 {fi}",self.m.funcs.len()));let fun=self.raw(format!("load ptr, ptr {pp}"));let t=self.m.types[i.a as usize].clone();self.call(&t,&fun)?;},
            26=>{self.any()?;},27=>{let c=self.pop(Ty::I32)?;let b=self.any()?;let a=self.pop(b.ty)?;let c=self.raw(format!("icmp ne i32 {}, 0",c.v));let v=self.value(a.ty,format!("select i1 {c}, {} {}, {} {}",a.ty.llvm(),a.v,b.ty.llvm(),b.v));self.push(v);},
            32=>{let ty=self.local_type(i.a);let v=self.value(ty,format!("load {}, ptr %l{}, align 1",ty.llvm(),i.a));self.push(v);},
            33|34=>{let ty=self.local_type(i.a);let v=self.pop(ty)?;self.line(format!("store {} {}, ptr %l{}, align 1",ty.llvm(),v.v,i.a));if i.op==34{self.push(v)}},
            35=>{let ty=self.m.globals[i.a as usize].ty;let v=self.value(ty,format!("load {}, ptr @g{}",ty.llvm(),i.a));self.push(v);},
            36=>{let ty=self.m.globals[i.a as usize].ty;let v=self.pop(ty)?;self.line(format!("store {} {}, ptr @g{}",ty.llvm(),v.v,i.a));},
