            63=>{let n=self.raw("load i64, ptr @mem.size");let n=self.raw(format!("lshr i64 {n}, 16"));let v=self.value(Ty::I32,format!("trunc i64 {n} to i32"));self.push(v);},
            64=>{let n=self.pop(Ty::I32)?;let v=self.value(Ty::I32,format!("call i32 @memory.grow(i32 {})",n.v));self.push(v);},
            65=>self.push(Val{ty:Ty::I32,v:(i.imm as i32).to_string()}),66=>self.push(Val{ty:Ty::I64,v:i.imm.to_string()}),
            67=>{let bits=u32::from_le_bytes(i.bytes[..4].try_into().unwrap());let v=self.value(Ty::F32,format!("bitcast i32 {bits} to float"));self.push(v);},
            68=>{let bits=u64::from_le_bytes(i.bytes[..8].try_into().unwrap());let v=self.value(Ty::F64,format!("bitcast i64 {bits} to double"));self.push(v);},
            69..=196=>self.numeric(i.op)?,
            0xfc00..=0xfc07=>self.convert_sat(i.op-0xfc00)?,
            0xfc08..=0xfc0e=>self.bulk(i)?,
            0xfd00..=0xfdff=>crate::simd::emit(self,i)?,
            _=>return Err(format!("unsupported opcode {:x}",i.op)),
        }Ok(())
    }
    fn local_type(&self,i:u32)->Ty {self.locals[i as usize]}
    fn memory(&mut self,i:&Instr)->Result<(),String> {
        let (t,bits,signed,store)=match i.op {
            40=>(Ty::I32,32,false,false),41=>(Ty::I64,64,false,false),42=>(Ty::F32,32,false,false),43=>(Ty::F64,64,false,false),
