            48=>(Ty::I64,8,true,false),49=>(Ty::I64,8,false,false),50=>(Ty::I64,16,true,false),51=>(Ty::I64,16,false,false),52=>(Ty::I64,32,true,false),53=>(Ty::I64,32,false,false),
            54=>(Ty::I32,32,false,true),55=>(Ty::I64,64,false,true),56=>(Ty::F32,32,false,true),57=>(Ty::F64,64,false,true),58=>(Ty::I32,8,false,true),59=>(Ty::I32,16,false,true),60=>(Ty::I64,8,false,true),61=>(Ty::I64,16,false,true),62=>(Ty::I64,32,false,true),_=>unreachable!()};
